(function(){"use strict";function a(t,s){const e=t.trim().toLowerCase(),r=s.toLowerCase();if(!e)return 1;if(r===e)return 100;if(r.startsWith(e))return 80;let c=0,o=0;for(const i of e){const n=r.indexOf(i,o);if(n<0)return 0;c+=10-Math.min(n-o,8),o=n+1}return c}function f(t,s){return s.map(e=>({...e,score:a(t,e.text)})).filter(e=>e.score>0).sort((e,r)=>r.score-e.score||e.text.localeCompare(r.text))}self.onmessage=t=>{const s=f(t.data.query,t.data.items).slice(0,30);self.postMessage(s)}})();
